        # and dynamo rejects the nested set rather than creating the parent
        connections_table.update_item(
            Key={"id": connection_id},
            UpdateExpression="SET historical_sync_completed = if_not_exists(historical_sync_completed, :empty)",
            ExpressionAttributeValues={":empty": {}},
            # without this, updating a connection that doesn't exist yet (deleted
            # mid-crawl, or a test's fake id) creates a bare row with no org_id
            ConditionExpression=Attr("id").exists(),
        )
        connections_table.update_item(
            Key={"id": connection_id},
            UpdateExpression="SET historical_sync_completed.#function_name = :true",
            ExpressionAttributeNames={"#function_name": function_name},
            ExpressionAttributeValues={":true": True},
            ConditionExpression=Attr("id").exists(),
        )
    except ClientError as e:
        if e.response["Error"]["Code"] != "ConditionalCheckFailedException":
            raise

