    def get_table_meta(self, table_name):
        if table_name not in self.tables:
            table = self.dynamodb.Table(table_name)
            self.tables[table_name] = {
                "key_names": [schema["AttributeName"] for schema in table.key_schema],
                "indexes": table.global_secondary_indexes or [],
            }
        return self.tables[table_name]

    def record_write(self, params, model, **kwargs):
        if not self.enabled:
            return
        if model.name == "BatchWriteItem":
            for table_name, requests in params["RequestItems"].items():
                for request in requests:
                    if "PutRequest" in request:
                        self.record_row(table_name, request["PutRequest"]["Item"])
                    else:
                        self.record_key(table_name, request["DeleteRequest"]["Key"])
        elif model.name == "PutItem":
            self.record_row(params["TableName"], params["Item"])
        else:
            self.record_key(params["TableName"], params["Key"])

    def record_row(self, table_name, row):
        key = {}
        for name in self.get_table_meta(table_name)["key_names"]:
            key[name] = row[name]
        self.mark_unchecked(table_name, key, row)

    def record_key(self, table_name, key):
        # boto3 rewrites params into wire format after this hook runs, so keep a copy
        key = dict(key)
        # an update or delete doesn't carry the row, so read where the index may still
        # hold it before it changes
        if self.get_table_meta(table_name)["indexes"]:
            self.mark_unchecked(table_name, key, self.get_row(table_name, key))

    def mark_unchecked(self, table_name, key, row):
        meta = self.get_table_meta(table_name)
        key_values = tuple(key[name] for name in meta["key_names"])
        for index in meta["indexes"]:
            self.unchecked_keys[(table_name, index["IndexName"])][key_values] = key
            position = get_index_position(index, row)
            if position is not None:
                self.index_positions[(table_name, index["IndexName"], key_values)].add(
                    position
                )

    def prepare_read(self, params, model, **kwargs):
        if not self.enabled:
            return
        if model.name == "BatchGetItem":
            for request in params["RequestItems"].values():
                request["ConsistentRead"] = True
        elif "IndexName" in params:
            self.wait_for_index(params["TableName"], params["IndexName"])
        else:
            params["ConsistentRead"] = True

    def fail_untracked_call(self, model, **kwargs):
        if self.enabled:
            pytest.fail(
                f"test reads can't wait on DynamoDB {model.name} yet; teach "
                "ConsistentReads in test/conftest.py about it"
            )

    def wait_for_index(self, table_name, index_name):
        index = None
        for candidate in self.get_table_meta(table_name)["indexes"]:
            if candidate["IndexName"] == index_name:
                index = candidate
        unchecked = self.unchecked_keys[(table_name, index_name)]
        deadline = time.time() + INDEX_WAIT_SECONDS
        while unchecked:
            for key_values, key in list(unchecked.items()):
                if self.index_matches_table(table_name, index, key_values, key):
                    unchecked.pop(key_values, None)
            if not unchecked:
                return
            if time.time() > deadline:
                pytest.fail(
                    f"{index_name} on {table_name} still doesn't match the table "
                    f"after {INDEX_WAIT_SECONDS}s for {list(unchecked.values())}"
                )
            time.sleep(0.2)

    def index_matches_table(self, table_name, index, key_values, key):
        positions = self.index_positions[(table_name, index["IndexName"], key_values)]
        current = self.get_row(table_name, key)
        current_position = get_index_position(index, current)
        if current_position is not None:
            index_row = self.get_index_row(table_name, index, current_position, key)
            if index_row != self.project(table_name, index, current):
                return False
        # an index can add a row's new entry before it drops the old one, so every
        # other place the row sat has to be empty too
        for position in positions - {current_position}:
            if self.get_index_row(table_name, index, position, key) is not None:
                return False
        positions.clear()
        if current_position is not None:
            positions.add(current_position)
        return True

    def get_row(self, table_name, key):
        table = self.dynamodb.Table(table_name)
        return table.get_item(Key=key, ConsistentRead=True).get("Item")

    def get_index_row(self, table_name, index, position, key):
        index_key_names = [schema["AttributeName"] for schema in index["KeySchema"]]
        condition = None
        for name, value in zip(index_key_names, position):
            part = Key(name).eq(value)
            condition = part if condition is None else condition & part
        query_args = {
            "IndexName": index["IndexName"],
            "KeyConditionExpression": condition,
        }
        # a filter can't name the index's own keys; the key condition already pins those
        key_filter = None
        for name, value in key.items():
            if name not in index_key_names:
                part = Attr(name).eq(value)
                key_filter = part if key_filter is None else key_filter & part
        if key_filter is not None:
            query_args["FilterExpression"] = key_filter
        table = self.dynamodb.Table(table_name)
        while True:
            response = table.query(**query_args)
            if response["Items"]:
                return response["Items"][0]
            if "LastEvaluatedKey" not in response:
                return None
            query_args["ExclusiveStartKey"] = response["LastEvaluatedKey"]

    def project(self, table_name, index, row):
        projection = index["Projection"]
        if projection["ProjectionType"] == "ALL":
            return row
        names = set(self.get_table_meta(table_name)["key_names"])
        for schema in index["KeySchema"]:
            names.add(schema["AttributeName"])
        names.update(projection.get("NonKeyAttributes", []))
        return {name: value for name, value in row.items() if name in names}


